type getByIdUseCaseMock struct {
	execute func(searchCtx gainprojection.SearchContext) (*gainprojection.GainProjectionResponse, error)
}

func (m *getByIdUseCaseMock) Execute(searchCtx gainprojection.SearchContext) (*gainprojection.GainProjectionResponse, error) {
	return m.execute(searchCtx)
}

func TestGetByIdSuccess(t *testing.T) {
	useCaseMock := &getByIdUseCaseMock{
		execute: func(searchCtx gainprojection.SearchContext) (*gainprojection.GainProjectionResponse, error) {
			return &gainprojection.GainProjectionResponse{Id: "9b15034f-85fe-4476-82b1-a95f438aadd5"}, nil
		},
	}

	handler := NewGetByIdHandler(useCaseMock)
	w := httptest.NewRecorder()
	router := gin.Default()
	apiRouter := router.Group("/v1")
	apiRouter.GET("/gain-projection/:id", handler.Handle)

	req, _ := http.NewRequest("GET", "/v1/gain-projection/9b15034f-85fe-4476-82b1-a95f438aadd5", nil)
	userToken := "eyJhbGciOiJSUzI1NiIsInR5cCIgOiAiSldUIiwia2lkIiA6ICJRSnVoUjlFSFBIWTZFT195VjV4M1BTZWUzakRLNUs4M0lQMjJwYjFxZXFvIn0..AcRSnpgzjsuJL2n_QaRF1idkwDzwNpWNX3wiEOFXkqTG35lr4PYVYPxnhryvRvVVOvN_CUY-AaVmF_YSgR4s6JM3Oca5JFFf7T6fX5lXgj0SbQCUbbyh7Em3BemiNKr_T3wucAyO824MjGXP0smciCnnlWvq-apJDTB_R4EisDJubY_E_zpCmTfYMm0NcJ8aKB2ku8mACKgE2ZJ7WsHkKNmjaFeyU9KjGMmNKtFthYISKqRQW-6u2xPjCkpFt4_HoJ01PgjFrrJacWDlUHxVoSILcaH_Vg-WHrKppIkzgdOg5phB2zVtcakRhPhqzV4EX_jXJp2SgK4umf6ivTC3lg"
	req.Header.Add(idpauth.AUTH_HEADER, userToken)

	router.ServeHTTP(w, req)
	bodyExpected := `{"id":"9b15034f-85fe-4476-82b1-a95f438aadd5","pay_in":"0001-01-01T00:00:00Z","description":"","value":0,"is_passive":false,"category":{"id":0,"category":""}}`
	assert.Equal(t, bodyExpected, w.Body.String())
	assert.Equal(t, http.StatusOK, w.Code)
}

